def orbit(r,c):
 seen={(r,c)}; todo=[(r,c)]
 while todo:
  a,b=todo.pop()
  candidates=[(b,a)]
  if 0<=31-a<30: candidates.append((31-a,b))
  for q in candidates:
   if q not in seen: seen.add(q);todo.append(q)
 return seen
